/* ModelQuest v9 — prerequisite-first teaching system: WHY → HOW → WHEN → WHAT. */
(()=>{
const CH={
1:{name:'Linear Regression',question:'A sensor gives us voltage, but the quantity we care about is force. How could a computer learn the connection from tests we already performed?',have:'During calibration we can record both the voltage and the known force.',need:'Later we may only have voltage, but still need an estimate of force.',simple:'One measurement is not enough to tell us how every future voltage behaves. We need several examples and a reusable relationship.',chain:[
['Why collect more than one example?','One pair only tells us what happened once. Several pairs let us see whether a repeatable pattern exists.'],
['Why put the values on a graph?','A table stores the measurements; a graph makes the way the two quantities move together easier to see.'],
['Why look at change instead of only the raw values?','We want to know how much force tends to change when voltage changes. That rate is more useful than memorizing each row.'],
['Why does a straight line enter the story?','The sample changes are close to constant: about +10 N for about +0.4 V. A constant rate of change is represented by a straight line.'],
['Why do we need learning at all?','Real measurements are noisy, so many slightly different lines are possible. We need a repeatable way to choose the one that fits the examples best.']],
how:[
['Collect examples','Apply known forces and record the voltage each time.'],['See the pattern','Plot each voltage-force pair as one point.'],['Describe the rate','Compare change in force with change in voltage. This rate is later called slope.'],['Try a simple rule','Because the rate is roughly constant, try one straight line instead of an unnecessarily flexible curve.'],['Judge the rule','Compare the line’s predictions with the known forces and measure the mistakes.'],['Improve the rule','Adjust the line until the overall mistake is as small as we can make it.']],
when:['The output is a number.','The relationship looks roughly straight over the operating range.','You want an interpretable baseline or calibration rule.'],avoid:['The points clearly bend in a systematic curve.','Important relationships are highly nonlinear or interactive.','A few extreme measurements dominate without investigation.'],
terms:[['Slope','We needed one number for “how much force changes per volt.”','change in output ÷ change in input'],['Intercept','We needed a way to move the whole line up or down without changing its steepness.','the line’s offset'],['Loss','We needed one score for how bad the whole line is, not dozens of separate errors.','overall mistake score'],['Gradient','Once a line is wrong, we need to know which parameter change would make loss go down.','direction/sensitivity of loss'],['Learning rate','Knowing the direction is not enough; we must choose how large a correction to make.','size of each update']],mathNeed:'The math exists to turn “this line looks better” into a repeatable calculation: describe the line, measure its errors, and adjust its parameters systematically.'},
2:{name:'Logistic Regression',question:'Inspection gives us measurements, but the final decision is PASS or FAIL. How can examples teach a computer to make that kind of decision?',have:'Historical parts contain measurements such as thickness error and roughness, plus the inspection result.',need:'For a new part we need a defensible PASS/FAIL decision before the answer is known.',simple:'A normal straight-line number prediction can produce values below 0 or above 1, which do not make sense as a bounded decision score.',chain:[['Why is this different from Chapter 1?','Force was a continuous number. Here the answer belongs to one of two groups.'],['Why not predict PASS as 1 and FAIL as 0 with an ordinary line?','A line can predict values such as -0.4 or 1.3. We need an output that stays within a sensible decision range.'],['Why produce a score before a final decision?','A borderline part and an obvious failure should not look identical. A score lets us express strength of evidence.'],['Why do we need a threshold?','A score such as 0.72 still is not a shop-floor action. We need a cutoff that converts the score into PASS or FAIL.'],['Why do different mistakes matter?','Rejecting a good part and accepting a defective one can have very different costs.']],how:[['Start with labeled examples','Each old part has measurements and a known PASS/FAIL result.'],['Combine the measurements','The model learns how each measurement pushes the decision toward one class or the other.'],['Keep the output bounded','Transform the raw score into a value between 0 and 1.'],['Choose a threshold','Convert that score into a final class decision.'],['Count each kind of mistake','Separate false alarms from missed defects instead of hiding everything inside accuracy.']],when:['The answer has two classes.','You want an interpretable probability-like score.','A relatively simple decision boundary is a useful baseline.'],avoid:['The class boundary is strongly nonlinear without useful feature engineering.','Classes are not meaningfully separable with the available measurements.','A threshold is chosen without considering business or safety consequences.'],terms:[['Classification','We are predicting a group rather than a free-running number.','choosing a class'],['Probability score','We need a bounded measure of how strongly evidence points toward a class.','score between 0 and 1'],['Threshold','We need to turn a score into an operational decision.','decision cutoff'],['Precision','False alarms can be expensive, so we ask how trustworthy positive alarms are.','when we say YES, how often are we right?'],['Recall','Missed defects can be dangerous, so we ask how many real positives we caught.','of the real YES cases, how many did we find?']],mathNeed:'The math converts several measurements into a bounded score and then lets us reason precisely about thresholds and the different kinds of errors.'},
3:{name:'KNN + SVM',question:'A new machine reading appears. Without a simple formula, can we decide which known operating state it most resembles—or learn a boundary between states?',have:'We have old vibration, temperature and load readings whose operating states are already known.',need:'We need to label a new reading whose state is unknown.',simple:'A single straight numeric relationship is not enough because the answer is a category and the groups may occupy different regions of the measurement space.',chain:[['Why does “similar” matter?','If a new reading looks like old NORMAL readings, those nearby examples contain useful evidence.'],['Why does a computer need distance?','Humans can see nearby dots. A computer needs a number that measures how far two examples are from each other.'],['Why ask several neighbors instead of one?','The single nearest example may be noisy or unusual. A small neighborhood gives a more stable vote.'],['Why can units distort similarity?','100 degrees and 2 mm/s live on very different numeric scales. Distance can be dominated by the larger scale.'],['Why consider a boundary instead?','Rather than consulting neighbors every time, we may want one learned divider with breathing room between classes.']],how:[['Represent each machine reading as a point','Its measurements become coordinates.'],['KNN: find nearby known points','Measure distance, select K neighbors, and let their labels vote.'],['Scale first when needed','Put features on comparable scales so one unit does not unfairly dominate distance.'],['SVM: search for a separator','Find a boundary between classes.'],['Prefer breathing room','Choose a boundary with a wide margin from the most influential edge examples.'],['Allow curvature when justified','If a straight separator cannot work, a kernel can represent a more flexible boundary.']],when:['KNN: local similarity is meaningful and the dataset is manageable.','SVM: a clear margin exists in small-to-medium, properly scaled data.','You want to compare instance-based reasoning with a learned boundary.'],avoid:['Distance is meaningless because features are unscaled or irrelevant.','KNN prediction must serve an enormous dataset with tight latency.','SVM parameters or kernels are chosen without understanding boundary behavior.'],terms:[['Distance','We need to turn “these examples look close” into a number.','numerical separation between examples'],['K','One neighbor may be noisy, so we choose how many nearby examples vote.','number of neighbors'],['Scaling','Different units can distort distance, so we put features on comparable numeric footing.','rescaling features'],['Margin','Several boundaries may separate the classes; we want breathing room.','gap between boundary and closest examples'],['Support vector','Only some edge examples determine the boundary most strongly.','influential boundary example']],mathNeed:'The math gives “similarity” and “separation” exact meanings through distance, voting, margins and boundary equations.'},
4:{name:'Decision Tree',question:'A project team already reasons with questions such as “Is supplier backlog high?” Can a model learn a useful sequence of questions from past shipments?',have:'Past shipments include route, supplier queue and shipment conditions plus whether each delivery was late.',need:'For a new shipment we want a readable estimate of late/on-time risk.',simple:'One global line or boundary may miss useful threshold rules and interactions such as “long distance matters mainly when supplier queue is already high.”',chain:[['Why ask a question at all?','A yes/no question can divide mixed examples into two groups that are easier to reason about.'],['Why ask another question?','One split may still leave late and on-time shipments mixed together.'],['What makes one question better than another?','A useful split creates groups that are more internally consistent.'],['Why stop splitting?','If we keep asking questions until every old example is memorized, the rules may become brittle on new shipments.'],['Why is readability useful?','Operations teams often need to understand which conditions drove the decision.']],how:[['Start with all shipments together','The group contains a mixture of late and on-time outcomes.'],['Try candidate questions','Test thresholds such as queue > 8 hours.'],['Choose the question that improves separation','Prefer splits that make the child groups less mixed.'],['Repeat inside each group','Build branches only where another question adds value.'],['Stop before memorization','Limit depth or require enough examples in each leaf.']],when:['Threshold-like rules and interactions are plausible.','Interpretability matters.','You want a nonlinear tabular model with little preprocessing.'],avoid:['The tree is allowed to grow until it memorizes tiny accidents in training data.','Small data changes create wildly different trees and stability matters.','You treat learned branches as causal rules.'],terms:[['Split','We need a question that divides the examples.','one decision rule'],['Node','We need a place where a question is asked.','decision point'],['Leaf','Eventually we need an answer rather than another question.','final group/prediction'],['Impurity','We need to score how mixed a group is.','measure of class mixture'],['Depth','We need to control how many layers of questions the tree can grow.','number of decision levels']],mathNeed:'The math helps the tree compare thousands of possible questions objectively and quantify how much each split makes the groups less mixed.'},
5:{name:'Random Forest + Boosting',question:'One decision tree can change a lot when the training sample changes slightly. Can several imperfect trees produce a more reliable maintenance warning together?',have:'We have labeled maintenance history with vibration, temperature, current, age and observed outcomes.',need:'We want a stable failure-risk prediction, especially when failures are rare and costly to miss.',simple:'A single tree can be unstable: small changes in data can change its early splits and therefore much of the tree.',chain:[['Why not trust one tree?','One tree can overreact to peculiarities in one sample.'],['Why would many trees help?','If different trees make different mistakes, combining them can cancel some individual errors.'],['Why must the trees differ?','Twenty identical trees are still one opinion repeated twenty times.'],['Why does boosting use a different idea?','Instead of independent opinions, later trees can concentrate on errors earlier trees failed to handle.'],['Why is accuracy dangerous for failures?','If 98% of machines are healthy, always saying HEALTHY already gets 98% accuracy while catching zero failures.']],how:[['Forest: create varied training views','Give trees different row samples and feature subsets.'],['Train many trees','Each tree learns its own set of rules.'],['Combine their decisions','Vote for classification or average for numeric prediction.'],['Boosting: learn sequentially','Let each new learner focus more on previous mistakes.'],['Judge the right mistakes','Use recall, precision and real failure costs—not accuracy alone.']],when:['Tabular industrial data contains nonlinear interactions.','You need a strong practical baseline.','A single tree is too unstable but full deep learning is unnecessary.'],avoid:['Leakage gives the forest future information.','Class imbalance is ignored.','Feature importance is treated as proof of causation.'],terms:[['Ensemble','One model is unstable, so we combine several models.','group of models'],['Bagging','We need varied training views for independent trees.','training models on resampled data'],['Random Forest','We combine many randomized trees to stabilize predictions.','tree ensemble'],['Boosting','We want later learners to focus on earlier mistakes.','sequential error-correcting ensemble'],['Class imbalance','Rare failures can disappear inside overall accuracy.','unequal class frequencies']],mathNeed:'The math explains how resampling, voting, averaging and sequential error correction can reduce instability and focus learning on difficult cases.'},
6:{name:'K-Means + PCA',question:'We have months of machine telemetry, but nobody labeled the operating states. Can the data reveal useful structure without being given the answers?',have:'RPM, current, vibration, temperature and acoustic measurements are recorded, but no state label accompanies each row.',need:'We want to discover recurring operating modes and make high-dimensional data easier to inspect.',simple:'Supervised models from earlier chapters depended on known answers. Here those answers do not exist.',chain:[['Why can learning happen without labels?','Even without answers, examples can still be similar, different, dense, sparse or arranged into recurring patterns.'],['Why group nearby points?','If operating modes produce similar telemetry, nearby observations may belong to the same regime.'],['Why do we need centers?','A center gives each tentative group a simple representative location.'],['Why must we choose K?','The algorithm needs to know how many centers to maintain, but that number is a modelling choice—not proof that nature has exactly K modes.'],['Why reduce dimensions?','Five or ten sensor dimensions cannot be viewed directly on a normal 2D screen. We need a lower-dimensional view that preserves important variation.']],how:[['K-Means: place K tentative centers','Start with candidate representatives.'],['Assign points to their nearest center','Form provisional groups.'],['Move each center to its group average','Update the representative.'],['Repeat until assignments settle','Alternate assignment and movement.'],['PCA: search for informative directions','Find directions that preserve as much variation as possible.'],['Project onto fewer axes','Create a simpler view while acknowledging some information is lost.']],when:['K-Means: unlabeled numeric data may contain compact groups.','PCA: many correlated numeric features need visualization or compression.','You are exploring structure rather than claiming a known ground truth.'],avoid:['You assume K-Means clusters automatically equal real machine modes.','Features are unscaled even though distance matters.','PCA components are treated as if they were original physical variables.'],terms:[['Unsupervised learning','We have examples but no provided answers.','learning structure without labels'],['Cluster','We need a name for a group of similar observations.','group of nearby/similar examples'],['Centroid','We need one representative center for a cluster.','cluster average position'],['Dimension','Each measured variable adds another coordinate direction.','one feature axis'],['Principal component','We need a new direction that preserves large variation.','compressed variance-preserving axis']],mathNeed:'The math formalizes “nearby,” “center,” and “preserve as much variation as possible” so grouping and compression are reproducible rather than visual guesses.'},
7:{name:'Neural Network / MLP',question:'What if machine state depends on several sensor signals interacting in ways that a simple line or a few hand-like splits cannot represent?',have:'We have many labeled sensor examples and already know how simpler models describe lines, boundaries and decision rules.',need:'We need a more flexible function that can combine several signals and learn nonlinear interactions.',simple:'A single linear rule cannot bend, while one small tree may need many brittle branches to approximate a smooth complex pattern.',chain:[['Why should one input matter more than another?','Vibration may be a stronger clue than ambient temperature. We need adjustable influence.'],['How can we represent influence numerically?','Multiply each input by a learned number. Only after this need is clear do we call that multiplier a weight.'],['Why add an offset?','The calculation may need a movable starting point even when inputs are zero. That creates the need for bias.'],['Why is one weighted calculation still limited?','A linear combination still produces a linear relationship. We need a way to introduce bends.'],['Why use many units and layers?','Different units can learn different intermediate patterns, and later layers can combine them.'],['Why do we need backpropagation?','When the final answer is wrong, thousands of internal parameters may share responsibility. We need an efficient way to trace how each parameter affected the loss.']],how:[['Combine inputs with adjustable multipliers','Create a weighted sum plus an offset.'],['Apply a nonlinear activation','Allow the calculation to bend instead of remaining purely linear.'],['Repeat many small units','Let different units respond to different patterns.'],['Stack layers','Let later units combine earlier learned patterns.'],['Measure final loss','Compare network output with known answers.'],['Send responsibility backward','Compute how each parameter influenced loss, then let an optimizer update them.']],when:['Relationships are complex and nonlinear.','Enough representative data and compute are available.','Simpler models have been tried and cannot capture useful structure.'],avoid:['A small tabular problem is solved adequately by a simpler interpretable model.','Training data is too limited or unrepresentative.','Network size is increased without diagnosing the actual error.'],terms:[['Weight','We need adjustable influence for each signal.','learned multiplier'],['Bias','We need an adjustable starting offset.','learned additive value'],['Activation','Linear pieces alone cannot create complex bends.','nonlinear transformation'],['Layer','We need to organize many intermediate calculations.','group of neurons at one stage'],['Backpropagation','We need to know how internal parameters contributed to the final loss.','efficient backward gradient calculation']],mathNeed:'The math composes many simple weighted calculations, introduces nonlinearity, and uses the chain rule to assign responsibility for error through the entire network.'},
8:{name:'Generalization + Regularization',question:'A model scores almost perfectly on old production data. Why can it still fail badly when a new batch or supplier appears?',have:'We have a trained model and excellent performance on examples it has already seen.',need:'We need confidence that the model learned something that remains useful on future, unseen production.',simple:'Training performance alone cannot distinguish genuine learning from memorizing noise, leakage or quirks of one batch.',chain:[['Why is unseen data the real test?','The model exists to handle tomorrow’s cases, not to recite yesterday’s answers.'],['Why can a more flexible model be worse?','It can follow every accidental wiggle in training data instead of the stable relationship.'],['Why keep validation/test data separate?','If the model repeatedly practices on evaluation examples, the evaluation stops being an honest surprise.'],['Why intentionally constrain a model?','When flexibility encourages memorization, we may prefer a simpler or less extreme solution.'],['Why can the world itself break the model?','Even a well-generalized model can fail if supplier, machine or process conditions change.']],how:[['Separate learning from evaluation','Train on one set and reserve unseen examples for checking.'],['Compare training and validation behavior','A widening gap can reveal overfitting.'],['Reduce unnecessary flexibility','Use simpler structure, penalties, dropout or early stopping when appropriate.'],['Check the data generation process','Look for leakage and duplicated/future information.'],['Test new conditions','Evaluate across batches, suppliers, time periods or machines that reflect deployment.']],when:['Every real ML project needs generalization checks.','Regularization is useful when model flexibility exceeds what the data can support.','Distribution shift is plausible between training and deployment.'],avoid:['You tune repeatedly on the final test set.','You call every future failure “overfitting” without checking whether the world changed.','You use regularization as a substitute for fixing bad or leaked data.'],terms:[['Generalization','We need performance on cases the model did not practice on.','ability to work on unseen data'],['Overfitting','The model can learn accidental training details too closely.','memorizing noise/quirks'],['Validation set','We need unseen examples while making modelling choices.','development evaluation data'],['Regularization','We need ways to discourage unnecessary complexity.','constraint or penalty on learning'],['Distribution shift','The deployment world may differ from the training world.','change in data conditions']],mathNeed:'The math helps quantify the tradeoff between fitting available examples and keeping the model stable enough to perform on unseen data.'},
9:{name:'CNN',question:'A surface photograph looks obvious to a human, but to a computer it is only a large grid of numbers. How can a model learn local visual patterns such as scratches and pits?',have:'We have labeled images of clean, scratched and pitted surfaces.',need:'We need a model that uses the spatial arrangement of nearby pixels instead of treating an image as an arbitrary list of numbers.',simple:'Flattening every pixel into one long list throws away the convenient idea that neighboring pixels form edges, textures and shapes.',chain:[['What is an image to a computer?','A grid of pixel values, not an object called “scratch.”'],['Why do nearby pixels matter?','Edges and textures are local arrangements; their meaning depends on spatial neighborhood.'],['Why inspect small windows repeatedly?','The same edge pattern may appear anywhere in the image, so one reusable local detector is efficient.'],['Why create feature maps?','We need to record where a filter responds strongly across the image.'],['Why stack layers?','Early local patterns such as edges can combine into textures and then larger defect structures.']],how:[['Slide a small window across the image','Inspect one local region at a time.'],['Apply the same learned filter everywhere','Measure how strongly that local pattern appears.'],['Build a feature map','Store the response at each location.'],['Reduce size carefully','Pooling can keep strong local evidence while shrinking the representation.'],['Stack learned filters','Build from simple edges toward more complex defect patterns.']],when:['Images or other grid-like spatial data are central.','Local patterns can appear in different positions.','Enough labeled visual examples are available.'],avoid:['Camera conditions change drastically and training images do not cover them.','You interpret one filter visualization as a complete explanation of the model.','A simple rule-based vision method already solves the task reliably.'],terms:[['Pixel','We need to know what numerical information the computer actually receives.','one image cell/value'],['Filter / kernel','We need a reusable small pattern detector.','small learned weight grid'],['Convolution','We need to apply that detector across many image locations.','sliding filter operation'],['Feature map','We need to store where the filter responded.','grid of filter responses'],['Pooling','Feature maps can be large, so we sometimes summarize local regions.','spatial downsampling']],mathNeed:'The math repeatedly multiplies a small filter with local pixel neighborhoods, producing feature maps that preserve spatial structure while learning useful visual detectors.'},
10:{name:'RNN / LSTM',question:'Two machines have the same power reading right now, but one has been rising and the other falling. How can a model use what happened before?',have:'We have ordered sensor readings across time.',need:'The next value or state may depend on history, not only the current measurement.',simple:'Treating every row as independent loses sequence order and makes two very different histories look identical at the current moment.',chain:[['Why does order matter?','20→25→30→35 tells a different story from 50→45→40→35 even though both end at 35.'],['Why keep memory?','The model needs some summary of earlier observations when processing the current one.'],['Why pass that memory forward?','Each new timestep should update what the model knows about the sequence so far.'],['Why can long-term memory fail?','During training, influence from far-back timesteps can become extremely weak.'],['Why invent gates?','We need a mechanism that can deliberately keep important information and discard irrelevant information.']],how:[['Read one timestep','Combine the current measurement with the previous memory.'],['Update the hidden state','Create a new summary and pass it forward.'],['Repeat through the sequence','Carry context from earlier readings.'],['For LSTM, control memory flow','Use gates to decide what to forget, add and expose.'],['Predict from sequence context','Use the accumulated state to estimate the next value or class.']],when:['Order is meaningful.','Recent or long-term history affects prediction.','Time-series or other sequential data is involved.'],avoid:['Rows are truly independent and order adds no information.','Random train/test splitting leaks future time into training.','A modern alternative such as a Transformer is more appropriate for the scale and task.'],terms:[['Sequence','Order itself carries information.','ordered examples'],['Timestep','We need a name for one position in the sequence.','one moment/position'],['Hidden state','We need a running summary of what came before.','carried memory vector'],['Vanishing gradient','Far-back events can stop influencing learning effectively.','weakening training signal through many steps'],['Gate','We need controlled memory flow.','learned keep/forget mechanism']],mathNeed:'The math reuses the same learned transformation across timesteps and carries a hidden state forward; LSTM gates add controlled paths for remembering and forgetting.'},
11:{name:'Transformer',question:'A maintenance note contains words whose meaning depends on other words around them. How can a computer represent the text and decide which parts of the sentence matter to each other?',have:'We have technician notes and examples of the information we want to extract.',need:'The model must represent words numerically while preserving context such as which component, problem and action belong together.',simple:'Giving each word an arbitrary ID does not capture meaning, and reading only nearby words can miss long-range relationships.',chain:[['Why split text into tokens?','Computers need manageable numerical units rather than raw sentences.'],['Why are token IDs insufficient?','ID 2817 being numerically close to ID 2818 does not mean their words have similar meanings.'],['Why create embeddings?','We need numerical representations where useful semantic relationships can be learned.'],['Why does context matter?','“Bearing” can mean a mechanical component or a direction; surrounding words resolve the meaning.'],['Why attention?','Each token needs a way to gather more information from the other tokens most relevant to interpreting it.'],['Why several attention heads?','Different relationships—component, timing, action, cause—can matter at the same time.']],how:[['Tokenize the note','Break text into model-readable pieces.'],['Convert tokens to embeddings','Represent each token with learned numbers.'],['Add position information','Keep track of order because token arrangement matters.'],['Compute attention','Let each token score which other tokens are relevant.'],['Mix relevant information','Build context-aware token representations.'],['Repeat through Transformer blocks','Refine the representations through attention and feed-forward stages.']],when:['Language or long-range context matters.','Large-scale sequence modelling benefits from parallel attention.','Pretrained language models provide useful starting representations.'],avoid:['You treat attention weights as a perfect explanation of model reasoning.','Token limits or context quality are ignored.','A simpler text rule or classical model already solves a narrow task reliably.'],terms:[['Token','Raw sentences must become model-readable pieces.','text unit'],['Embedding','Token IDs need meaningful numerical representations.','learned vector representation'],['Attention','A token needs relevant context from other tokens.','learned relevance-weighted information mixing'],['Query / Key / Value','We need a mechanism for asking, matching and carrying information.','three roles inside attention'],['Head','Different relationships may need separate attention patterns.','one attention subspace']],mathNeed:'The math turns tokens into vectors, computes relevance scores between them, normalizes those scores, and mixes information according to the resulting attention weights.'},
12:{name:'LoRA',question:'A pretrained language model already understands general text, but it does not reliably produce our maintenance-report format. Do we really need to retrain the whole model?',have:'We have a capable pretrained model and examples of technician notes paired with the output format we want.',need:'We want domain/format adaptation without the enormous cost of training or fully updating every parameter.',simple:'Training from scratch wastes knowledge the model already has, while full fine-tuning may require far more GPU memory than a small team can afford.',chain:[['Why start from a pretrained model?','Language knowledge is expensive to learn; we should reuse it when it already exists.'],['Why freeze most parameters?','We want to preserve the large base while avoiding the memory cost of updating everything.'],['Why add small trainable adapters?','A compact adjustment can steer behavior without rewriting the entire model.'],['Why does rank matter?','A tiny adapter has limited capacity; larger rank can represent richer changes but costs more memory and compute.'],['Why quantize?','Even frozen parameters consume memory, so storing them with fewer bits can make larger models fit on limited hardware.']],how:[['Load the pretrained base','Reuse its existing language capability.'],['Freeze the base weights','Keep most parameters unchanged.'],['Insert small trainable matrices','Add low-rank adapters to selected layers.'],['Train only the adapters','Learn the desired maintenance-report behavior from examples.'],['Optionally quantize the base','Reduce memory usage for constrained hardware.'],['Merge or load adapters at inference','Apply the learned specialization when generating reports.']],when:['A pretrained model already does most of the task.','You need domain/style/format adaptation.','GPU memory or training budget makes full fine-tuning unattractive.'],avoid:['You expect fine-tuning to inject constantly changing factual knowledge reliably.','Training examples are inconsistent or low quality.','You choose rank, quantization and batch size without checking memory and task behavior.'],terms:[['Pretrained model','We want to reuse expensive knowledge already learned.','model trained beforehand on broad data'],['Fine-tuning','We need to adapt existing behavior using new examples.','additional task/domain training'],['Frozen parameter','We want most of the base model to stay unchanged.','non-updated weight'],['Adapter','We need a small trainable adjustment around a large frozen model.','compact trainable module'],['Rank','We need to control adapter capacity versus cost.','size of low-rank adaptation'],['Quantization','Frozen weights still consume memory, so we may store them with fewer bits.','lower-precision parameter storage']],mathNeed:'The math represents a large weight update as the product of two much smaller matrices, dramatically reducing the number of trainable parameters while still allowing useful adaptation.'},
13:{name:'RAG + Tool Use',question:'A general AI model does not know our newest manuals, private service records or live sensor data. How can it answer using the right evidence instead of guessing?',have:'We have a language model plus external manuals, SOPs, service records and tools.',need:'We want current, grounded answers and sometimes calculations or data lookups that the base model cannot safely invent.',simple:'Retraining whenever a manual changes is wasteful, and asking the model from memory can produce confident but unsupported answers.',chain:[['Why retrieve information at question time?','Knowledge can change faster than we want to retrain the model.'],['Why split documents into chunks?','A 400-page manual contains far more context than one question needs.'],['Why use embeddings again?','We need a numerical way to compare the meaning of a question with the meaning of document chunks.'],['Why retrieve only the best matches?','Too little evidence can miss the answer; too much irrelevant evidence can bury it.'],['Why show sources?','A useful engineering answer should let the user inspect the evidence rather than trust fluent text blindly.'],['Why tools as well as documents?','Some questions require calculation, database lookup or another operation—not just reading text.']],how:[['Prepare documents','Split manuals and records into retrievable chunks.'],['Create embeddings','Represent chunks numerically for semantic comparison.'],['Embed the question','Represent the user request in the same space.'],['Retrieve top matches','Select the most relevant evidence.'],['Give evidence to the model','Generate an answer using the retrieved context.'],['Cite and verify','Show which chunks support the answer.'],['Call tools when necessary','Use calculators, databases or other actions for operations that text retrieval cannot perform.']],when:['Knowledge is private, changing or too large to bake into the model.','Evidence and source traceability matter.','The task needs retrieval, calculation or external system access.'],avoid:['Retrieved text is blindly trusted as instructions.','Poor retrieval is hidden behind a confident answer.','Sensitive tool actions occur without validation, permissions or confirmation.'],terms:[['Chunk','Whole documents are too large and unfocused for each query.','retrievable document segment'],['Embedding','Question and evidence need comparable semantic representations.','meaning-oriented numeric vector'],['Vector search','We need to find chunks whose meanings are closest to the question.','similarity retrieval'],['Top-K','We need to choose how many candidate chunks to pass forward.','number of retrieved results'],['Grounding','We want answers tied to supplied evidence.','answering from verifiable context'],['Tool call','Some answers require an operation rather than more text.','structured request to an external capability']],mathNeed:'The math measures semantic similarity between question and document vectors, ranks evidence, and passes selected context into generation; tool use adds structured decisions about when an external operation is required.'}
};
const STEP_LABELS=[['WHY','Why does this need to exist?'],['FOUNDATION','Build the ingredients'],['HOW','Watch the idea emerge'],['TRY IT','Change it yourself'],['WHY THE MATH','What problem does the math solve?'],['CODE','Tell the computer exactly what to do'],['WHEN','Use it—and know when not to'],['PROVE IT','Explain why before you run']];
function modelId(){const t=document.querySelector('.v5-quest-title .v5-kicker')?.textContent||'';const m=t.match(/MODEL\s+(\d+)/i);return m?+m[1]:0}
function stepIndex(){const steps=[...document.querySelectorAll('.v5-step')];return Math.max(0,steps.findIndex(x=>x.classList.contains('active')))}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function numbered(items,cls='mq9-sequence'){return `<div class="${cls}">${items.map((x,i)=>`<article><span>${String(i+1).padStart(2,'0')}</span><div><h3>${esc(x[0])}</h3><p>${esc(x[1])}</p></div></article>`).join('')}</div>`}
function termRows(c){return `<div class="mq9-terms">${c.terms.map(t=>`<article><div class="mq9-term-why">WHY DID WE NEED THIS?</div><h3>${esc(t[0])}</h3><p>${esc(t[1])}</p><div class="mq9-term-meaning"><b>Only now give it a name:</b> ${esc(t[2])}</div></article>`).join('')}</div>`}
function whyHTML(c){return `<div class="mq9-lesson mq9-why-screen"><div class="mq9-kicker">START WITH WHY · DO NOT MEMORIZE THE MODEL YET</div><h2>${esc(c.question)}</h2><div class="mq9-problem-line"><section><small>WHAT DO WE HAVE?</small><p>${esc(c.have)}</p></section><div class="mq9-arrow">→</div><section><small>WHAT ARE WE MISSING?</small><p>${esc(c.need)}</p></section></div><section class="mq9-friction"><small>WHY CAN'T WE JUST USE THE SIMPLEST THING WE ALREADY KNOW?</small><h3>Because there is a gap.</h3><p>${esc(c.simple)}</p></section><div class="mq9-kicker">BUILD THE NEED BEFORE THE VOCABULARY</div>${numbered(c.chain)}<section class="mq9-rule"><b>Learning rule for this course</b><p>Do not accept a new technical word until you can explain the problem that forced us to invent it.</p></section></div>`}
function foundationHTML(c,original){return `<div class="mq9-lesson"><div class="mq9-kicker">FOUNDATION · WHAT MUST MAKE SENSE BEFORE THE MODEL NAME</div><h2>Build the ingredients one at a time.</h2><p class="mq9-lead">The words below are not vocabulary to memorize. Each one exists because the previous idea created a new problem.</p>${termRows(c)}<details class="mq9-existing"><summary>Now connect this foundation to the actual examples</summary><div class="mq9-existing-inner">${original}</div></details></div>`}
function howHTML(c,id){let special='';if(id===1)special=`<div class="mq9-callout"><b>Notice the order:</b> relationship → rate of change → straight line → error → loss → improvement. <strong>“Linear Regression” is the name we give the completed method, not the starting point.</strong></div>`;if(id===7)special=`<div class="mq9-callout"><b>This chapter reuses old foundations:</b> slope became a general learned parameter, loss still measures wrongness, and Gradient Descent returns because the network now has many parameters instead of only two.</div>`;return `<div class="mq9-lesson"><div class="mq9-kicker">HOW · FIRST WATCH THE REASONING, THEN NAME IT</div><h2>How does the new idea solve the problem?</h2>${numbered(c.how,'mq9-sequence mq9-how')}<section class="mq9-reveal"><small>NOW THE NAME IS USEFUL</small><h2>${esc(c.name)}</h2><p>You have already built the reason for the method. The technical name is now just a label for the process you understand.</p></section>${special}</div>`}
function whenHTML(c,original){return `<div class="mq9-lesson"><div class="mq9-kicker">WHEN · MODEL CHOICE IS A JUDGMENT, NOT A HABIT</div><h2>When should this idea earn a place in the solution?</h2><div class="mq9-when-grid"><section><small>GOOD REASONS TO USE IT</small>${c.when.map(x=>`<p>✓ ${esc(x)}</p>`).join('')}</section><section><small>WARNING SIGNS / WHEN TO RECONSIDER</small>${c.avoid.map(x=>`<p>× ${esc(x)}</p>`).join('')}</section></div><details class="mq9-existing"><summary>Real-world traps and the original course examples</summary><div class="mq9-existing-inner">${original}</div></details></div>`}
function challengeHTML(c,original){return `<div class="mq9-lesson"><div class="mq9-kicker">PROVE IT · REASON BEFORE RESULT</div><h2>Before you click, train or reveal anything, explain why.</h2><div class="mq9-before-run"><label>1 · What problem are you solving?<textarea data-mq9-answer="problem" placeholder="Say it without using the model name."></textarea></label><label>2 · Why is this method reasonable here?<textarea data-mq9-answer="why" placeholder="Connect the data pattern/problem to the method."></textarea></label><label>3 · What result or failure do you expect?<textarea data-mq9-answer="predict" placeholder="Make a prediction before seeing the answer."></textarea></label></div><div class="mq9-callout"><b>Standard:</b> if the learner can operate the controls but cannot explain why the model exists, the chapter is not complete.</div><div class="mq9-existing-inner">${original}</div></div>`}
function mathPrefix(c,id){return `<section class="mq9-math-why"><div class="mq9-kicker">WHY DOES THIS MATH EXIST?</div><h2>The formula is a tool for a problem you already understand.</h2><p>${esc(c.mathNeed)}</p><div class="mq9-math-ladder"><span>1 · Say the problem in words</span><span>2 · Work one real-number example</span><span>3 · Show the formula</span><span>4 · Explain every symbol</span><span>5 · Connect it back to behavior</span></div></section>${id===1?gdLabHTML():id===7?minimaRevisitHTML():''}`}
function gdLabHTML(){return `<section class="mq9-gd" id="mq9Gd"><div class="mq9-kicker">GRADIENT DESCENT · SEE THE NEED BEFORE THE NAME</div><h2>Watch one bad line become a better line.</h2><p class="mq9-lead">The model has only two adjustable numbers here: the line's steepness and its vertical offset. We change them, measure whether the total error improves, and repeat. Use <b>One improvement step</b> first.</p><div class="mq9-gd-controls"><button type="button" data-gd="step">One improvement step</button><button type="button" data-gd="auto">Auto run</button><button type="button" data-gd="reset">Reset bad line</button><label>Step size <input type="range" min="1" max="100" value="20" data-gd="lr"><output data-gd="lrout">0.020</output></label></div><div class="mq9-gd-grid"><figure><figcaption><b>A · The line</b><span>Wrong predictions create visible gaps.</span></figcaption><svg viewBox="0 0 420 270" data-gd-svg="fit"></svg></figure><figure><figcaption><b>B · The loss landscape</b><span>Every slope + intercept gives a different total error.</span></figcaption><svg viewBox="0 0 420 270" data-gd-svg="land"></svg></figure><figure><figcaption><b>C · Loss over steps</b><span>If learning works, this should trend downward.</span></figcaption><svg viewBox="0 0 420 270" data-gd-svg="hist"></svg></figure></div><div class="mq9-gd-readout"><span>Steepness <b data-gd-val="m">12.00 N/V</b></span><span>Offset <b data-gd-val="b">2.00 N</b></span><span>Total mistake (MSE) <b data-gd-val="loss">—</b></span><span>Step <b data-gd-val="step">0</b></span></div><div class="mq9-gd-explain"><article><span>01</span><div><h3>Why measure loss?</h3><p>Five separate prediction errors are awkward to compare. Loss compresses the overall wrongness of one candidate line into one score.</p></div></article><article><span>02</span><div><h3>Why a gradient?</h3><p>Once the score is bad, we need to know which small change to slope and offset would make that score fall. The gradient supplies that local direction and sensitivity.</p></div></article><article><span>03</span><div><h3>Why “descent”?</h3><p>Imagine loss as height. Updating parameters toward lower loss is literally moving downhill on this landscape. Repeating that process is Gradient Descent.</p></div></article></div>${minimaRevisitHTML(true)}</section>`}
function minimaRevisitHTML(inner=false){return `<section class="mq9-minima ${inner?'inside':''}"><div><div class="mq9-kicker">LOCAL VS GLOBAL MINIMUM</div><h2>“Low nearby” is not always “lowest anywhere.”</h2><p><b>Global minimum:</b> the lowest loss available anywhere on the landscape. <b>Local minimum:</b> a point lower than its immediate surroundings even though a better valley exists elsewhere.</p><p>${inner?'For ordinary Linear Regression with squared error, the loss surface is convex—essentially one bowl—so the best solution is a global minimum.':'Neural-network landscapes are far more complicated than the simple bowl from Linear Regression. Local minima are one idea to understand, but flat regions and saddle points also affect optimization.'}</p></div><svg viewBox="0 0 560 230" aria-label="Local and global minimum illustration"><path d="M20 70 C80 15 125 185 190 125 C245 75 280 180 340 145 C410 105 445 210 535 55" fill="none" stroke="currentColor" stroke-width="4"/><line x1="183" y1="122" x2="183" y2="190" stroke="currentColor" stroke-dasharray="5 5" opacity=".45"/><circle cx="183" cy="122" r="7"/><text x="112" y="212">LOCAL MINIMUM</text><line x1="438" y1="181" x2="438" y2="215" stroke="currentColor" stroke-dasharray="5 5" opacity=".45"/><circle cx="438" cy="181" r="8"/><text x="365" y="228">GLOBAL MINIMUM</text></svg></section>`}
function codePrefix(c){return `<section class="mq9-code-why"><div class="mq9-kicker">CODE · THE SYNTAX COMES LAST</div><h2>Before reading the library call, say what the computer must do.</h2><p>By this point you should be able to describe ${esc(c.name)} without code. The code below is simply an exact set of instructions that performs the process you already understand.</p></section>`}
function enhance(){const id=modelId(),c=CH[id];if(!c)return;const s=stepIndex();document.querySelectorAll('.v5-step').forEach((el,i)=>{const x=STEP_LABELS[i];if(x)el.innerHTML=`<b>${i+1}. ${x[0]}</b>${x[1]}`});const basics=document.querySelector('#v5BasicsBtn');if(basics)basics.textContent='Prerequisites';const subtitle=document.querySelector('.v5-quest-title p');if(subtitle){if(s<2)subtitle.innerHTML='<b>Start with the problem.</b> The method name comes only after its purpose is clear.';else subtitle.innerHTML=`<b>${esc(c.name)}</b> · now connect the name to the reason it exists.`}const screen=document.querySelector('#v5Screen');if(!screen)return;const mark=`${id}-${s}`;if(screen.dataset.mq9===mark)return;const original=screen.innerHTML;if(s===0)screen.innerHTML=whyHTML(c);else if(s===1)screen.innerHTML=foundationHTML(c,original);else if(s===2)screen.innerHTML=howHTML(c,id);else if(s===3)screen.insertAdjacentHTML('afterbegin',`<section class="mq9-lab-intro"><div class="mq9-kicker">TRY IT · PREDICT BEFORE TOUCHING</div><h2>Change one thing only after you can say why that control exists.</h2><p>First predict the direction of change. Then move the control. Finally explain the result in plain language before using the technical term.</p></section>`);else if(s===4)screen.insertAdjacentHTML('afterbegin',mathPrefix(c,id));else if(s===5)screen.insertAdjacentHTML('afterbegin',codePrefix(c));else if(s===6)screen.innerHTML=whenHTML(c,original);else if(s===7)screen.innerHTML=challengeHTML(c,original);screen.dataset.mq9=mark;if(id===1&&s===4)initGD()}
let gdTimer=null;
function initGD(){const root=document.querySelector('#mq9Gd');if(!root||root.dataset.bound)return;root.dataset.bound='1';const pts=[[.42,10],[.81,20],[1.22,30],[1.60,40],[1.98,50]];let m=12,b=2,step=0,hist=[];const opt={m:25.57,b:-.84};const q=s=>root.querySelector(s);function loss(mm=m,bb=b){return pts.reduce((a,[x,y])=>a+(mm*x+bb-y)**2,0)/pts.length}function grad(){let dm=0,db=0;for(const [x,y] of pts){const e=m*x+b-y;dm+=2*e*x/pts.length;db+=2*e/pts.length}return[dm,db]}function line(x1,y1,x2,y2,extra=''){return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" ${extra}/>`}function renderFit(){const svg=q('[data-gd-svg="fit"]');if(!svg)return;const X=x=>42+x/2.2*345,Y=y=>230-y/60*190;let html=`${line(42,230,387,230,'stroke="#777"')}${line(42,40,42,230,'stroke="#777"')}`;for(const[x,y]of pts){const py=m*x+b;html+=line(X(x),Y(y),X(x),Y(py),'stroke="#777" stroke-dasharray="4 4"');html+=`<circle cx="${X(x)}" cy="${Y(y)}" r="5" fill="#fff"/>`}html+=line(X(0),Y(b),X(2.2),Y(m*2.2+b),'stroke="#fff" stroke-width="3"');html+=`<text x="52" y="55" fill="#aaa">force ↑</text><text x="315" y="252" fill="#aaa">voltage →</text>`;svg.innerHTML=html}function renderLand(){const svg=q('[data-gd-svg="land"]');if(!svg)return;const xm=mm=>55+(mm-5)/35*310,yb=bb=>225-(bb+15)/30*175;let html='<rect x="35" y="30" width="350" height="205" rx="20" fill="none" stroke="#333"/>';[1,2,3,4].forEach((k,i)=>html+=`<ellipse cx="${xm(opt.m)}" cy="${yb(opt.b)}" rx="${45+k*32}" ry="${24+k*18}" fill="none" stroke="#555" opacity="${.85-i*.15}"/>`);if(hist.length>1){const pp=hist.map(h=>`${xm(h.m)},${yb(h.b)}`).join(' ');html+=`<polyline points="${pp}" fill="none" stroke="#fff" stroke-width="2" opacity=".65"/>`}html+=`<circle cx="${xm(opt.m)}" cy="${yb(opt.b)}" r="7" fill="none" stroke="#fff" stroke-width="2"/><text x="${xm(opt.m)+10}" y="${yb(opt.b)-8}" fill="#aaa">lowest loss</text>`;html+=`<circle cx="${xm(m)}" cy="${yb(b)}" r="8" fill="#fff"/><text x="48" y="255" fill="#aaa">slope →</text><text x="300" y="54" fill="#aaa">offset axis</text>`;svg.innerHTML=html}function renderHist(){const svg=q('[data-gd-svg="hist"]');if(!svg)return;const values=hist.map(x=>x.loss),max=Math.max(1,...values,loss()),X=i=>45+(i/Math.max(1,Math.max(20,hist.length-1)))*335,Y=v=>225-(v/max)*175;let html=`${line(45,225,385,225,'stroke="#777"')}${line(45,40,45,225,'stroke="#777"')}`;if(values.length)html+=`<polyline points="${values.map((v,i)=>`${X(i)},${Y(v)}`).join(' ')}" fill="none" stroke="#fff" stroke-width="3"/>`;html+=`<text x="305" y="250" fill="#aaa">training step →</text><text x="50" y="55" fill="#aaa">loss ↑</text>`;svg.innerHTML=html}function render(){if(!hist.length)hist.push({m,b,loss:loss()});renderFit();renderLand();renderHist();q('[data-gd-val="m"]').textContent=m.toFixed(2)+' N/V';q('[data-gd-val="b"]').textContent=b.toFixed(2)+' N';q('[data-gd-val="loss"]').textContent=loss().toFixed(2);q('[data-gd-val="step"]').textContent=step}function one(){const lr=+q('[data-gd="lr"]').value/1000,[dm,db]=grad();m-=lr*dm;b-=lr*db;step++;hist.push({m,b,loss:loss()});render();if(step>200||!Number.isFinite(loss())||loss()>1e8)stop()}function stop(){if(gdTimer){clearInterval(gdTimer);gdTimer=null;const a=q('[data-gd="auto"]');if(a)a.textContent='Auto run'}}root.addEventListener('click',e=>{const a=e.target.closest('[data-gd]');if(!a)return;if(a.dataset.gd==='step')one();if(a.dataset.gd==='reset'){stop();m=12;b=2;step=0;hist=[];render()}if(a.dataset.gd==='auto'){if(gdTimer)stop();else{a.textContent='Pause';gdTimer=setInterval(one,220)}}});q('[data-gd="lr"]').addEventListener('input',e=>{q('[data-gd="lrout"]').textContent=(+e.target.value/1000).toFixed(3)});render()}
let scheduled=false;function schedule(){if(scheduled)return;scheduled=true;requestAnimationFrame(()=>{scheduled=false;enhance()})}const root=document.querySelector('#view');if(root)new MutationObserver(schedule).observe(root,{childList:true,subtree:true});document.addEventListener('click',e=>{if(e.target.closest('[data-v5step],#v5Next,#v5Prev,[data-v5go]'))setTimeout(schedule,0)});schedule();
})();